package fr.euphyllia.fidorial.server.registry.data;

import java.util.Base64;

/**
 * Per-BlockState opacity and light emission, indexed by network state id.
 *
 * <p>Generated from Mojang's blocks report and a bootstrap-time light-data dump; do not edit.</p>
 *
 * <p>Values are packed one byte per state (opacity in the high nibble, emission in the
 * low nibble) and stored Base64-encoded.
 */
public final class BlockStateLightProperties {
    private static final byte[] PACKED = Base64.getDecoder().decode("");

    private BlockStateLightProperties() {
        throw new UnsupportedOperationException();
    }

    public static int opacity(int stateId) {
        return (PACKED[stateId] >> 4) & 0xF;
    }

    public static int emission(int stateId) {
        return PACKED[stateId] & 0xF;
    }
}
